// Techlystb fallback JS
(function () {
  console.warn("⚠️ Techystb fallback JS activated");

  // Minimal fallback UI
  const fallbackBox = document.createElement("div");
  fallbackBox.innerHTML = `
    ⚠️ মূল ফিচার লোড হয়নি<br/>
    Fallback চালু হয়েছে।
    <button onclick="location.reload()" style="margin-top:5px;padding:3px 6px;">🔁 রিলোড</button>
  `;
  fallbackBox.style = `
    position:fixed;
    bottom:20px;
    left:20px;
    background:#ffe0e0;
    color:#000;
    padding:12px 16px;
    border:1px solid #cc0000;
    border-radius:8px;
    font-family:sans-serif;
    font-size:14px;
    box-shadow:0 0 12px rgba(0,0,0,0.15);
    z-index:9999;
  `;
  document.body.appendChild(fallbackBox);
})();
